// Returns { surah, ayah } for the first ayah of a given mushaf page, or null.
function pageStart(page) {
  if (page < 1 || page > 604) return null;
  const i = (page - 1) * 2;
  return { surah: PAGE_STARTS_FLAT[i], ayah: PAGE_STARTS_FLAT[i + 1] };
}

